func TestWatchTradesForSymbolsAsync(exchange ccxt.ICoreExchange, skippedProperties any, symbols any) <-chan ccxt.AsyncResult[any] {
	ch := make(chan ccxt.AsyncResult[any], 1)
	go testWatchTradesForSymbolsBody(ch, exchange, skippedProperties, symbols)
	return ch
}
func testWatchTradesForSymbolsBody(ch chan ccxt.AsyncResult[any], exchange ccxt.ICoreExchange, skippedProperties any, symbols any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var method string = "watchTradesForSymbols"
	var logText any = Add(Add(Add(Add(Add(exchange.GetId(), " "), method), " [symbols: "), exchange.Json(symbols)), "] ")
	var now int64 = exchange.Milliseconds()
	var ends int64 = now + 30000
	var symbolsLength int = GetArrayLength(symbols)
	var returnedSymbols []any = []any{}
	var allReceived bool = false
	// keep watching until every symbol traded or the deadline passed, a quiet market can stay silent for a while
	for (now < ends) && !allReceived {
		var response any = nil
		var success bool = true

		{
			func() (ret_ any) {
				defer func() {
					if e := recover(); e != nil {
						if e == "break" {
							return
						}
						ret_ = func() any {
							// catch block:
							if !EvalTruthy(IsTemporaryFailure(e)) {
								panic(e)
							}
							success = false
							return nil
						}()
					}
				}()
				// try block:

				r := <-exchange.(ccxt.IWatchTradesForSymbols).WatchTradesForSymbolsAsync(symbols)
				if r.Err != nil {
					panic(r.Err)
				}
				if r.Value == nil {
					response = nil
				} else {
					response = ccxt.TradesToList(r.Value)
				}
				return nil
			}()

		}
		now = exchange.Milliseconds()
		if (success) && (!IsEqual(response, nil)) {
			Assert(IsArray(response), Add(Add(logText, "must return an array. "), exchange.Json(response)))
			for i := 0; i < GetArrayLength(response); i++ {
				var trade any = GetValue(response, i)
				var symbol *string = SafeStringPtr(GetValue(trade, "symbol"))
				Assert((symbol != nil), Add(Add(logText, "returned a trade without a symbol "), exchange.Json(trade)))
				TestTrade(exchange, skippedProperties, method, trade, symbol, now, true)
				AssertInArray(exchange, skippedProperties, method, trade, "symbol", symbols)
				if !EvalTruthy(exchange.InArray(symbol, returnedSymbols)) {
					returnedSymbols = append(returnedSymbols, symbol)
				}
			}
			var returnedLength int = len(returnedSymbols)
			if returnedLength == symbolsLength {
				allReceived = true
			}
		}
	}
	var receivedLength int = len(returnedSymbols)
	Assert((receivedLength > 0), Add(logText, "did not receive trades for any symbol"))
	if !allReceived {
		// an illiquid symbol may not trade inside the window, that is the market and not a bug
		fmt.Println(Add(Add(logText, "warning: only received part of symbols before the deadline: "), exchange.Json(returnedSymbols)))
	}

	ch <- ccxt.AsyncResult[any]{Value: true}
	return nil
}
